    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i, n):
            if i == j:
                dp[i][j] = 1
            else:
                if s[i] == s[j]:
                    dp[i][j] = dp[i+1][j-1] + 1
                else:
                    dp[i][j] = max(dp[i+1][j], dp[i][j-1])
    return dp[0][n-1]

