```python
def shell_sort(arr):
    n = len(arr)
    gap = 1
    # Calculate gaps
    while gap < n//2:
        gap = 2 * gap + 1

    while gap > 0:
        gap //= 2

        if gap > 0:
            for i in range(gap, n):
            # Loop over the array elements
            j = i - 1
            while j >= 0:
                if j < 0 or arr[j] < arr[j + 1]:
                    break

                if j > 0 and arr[j] > arr[j + 1]:
                    arr[j], arr[j + 1] = arr[j + 1, arr[j]
                j -= 1
            j += 1
        else:
            return arr

    return arr

